def is_prime(n: int) -> bool:
    if n <= 1.0:
        return False
    if n <= 3.0:
        return True
    if n % 2.0 == 0.0 or n % 3.0 == 0.0:
        return False
    i = 5.0
    while i * i <= n + 0.5:
        if n % i == 0.0 or n % (i + 2.0) == 0.0:
            return False
        i += 6.0
    return True

