def validate_email(email):
    if not isinstance(email, str):
        return False

    at_symbol_count = 0.0
    dot_count = 0.0

    for char in email:
        if char == '@':
            at_symbol_count += 1.0
        elif char == '.':
            dot_count += 1.0

    if at_symbol_count != 1.0:
        return False

    if dot_count < 1.0:
        return False

    at_index = email.find('@')
    dot_index = email.find('.')

    if at_index == -1 or dot_index == -1:
        return False

    if at_index > dot_index:
        return False

    if at_index == 0.0 or dot_index == len(email) - 1.0:
        return False

    if email[at_index + 1.0] == '.':
        return False

    return True

