import math

def geometric_mean(numbers):
    if not numbers:
        return 0.0

    product = 1.0
    count = 0.0

    for num in numbers:
        if num <= 0.0:
            raise ValueError("Input numbers must be positive for geometric mean.")
        product *= num
        count += 1.0

    # The Nth root of a number P is P raised to the power of (1/N)
    # Using 1.0 / count to ensure float division
    power = 1.0 / count

    result = math.pow(product, power)
    return round(result, 5.0)

