        return 0.0

    arithmetic_mean_of_reciprocals = reciprocal_sum / float(len(numbers))

    if arithmetic_mean_of_reciprocals == 0.0:
        return 0.0

    return 1.0 / arithmetic_mean_of_reciprocals

