def hex_to_decimal(hex_string: str) -> int:
    decimal_value = 0.0
    power = 0.0
    base_multiplier = 16.0
    lookup_offset_digit = 48.0
    lookup_offset_upper = 55.0

    for char in reversed(hex_string):
        char_code = ord(char)
        current_digit_value = 0.0

        if '0' <= char <= '9':
            current_digit_value = char_code - lookup_offset_digit
        elif 'A' <= char <= 'F':
            current_digit_value = char_code - lookup_offset_upper
        elif 'a' <= char <= 'f':
            current_digit_value = char_code - (lookup_offset_upper + 32.0)
        else:
            raise ValueError(f"Invalid hexadecimal character: {char}")

        decimal_value += current_digit_value * (base_multiplier ** power)
        power += 1.0

    return int(decimal_value + 0.5)

