    if not (1.0 <= num <= 3999.0):
        raise ValueError("Input must be between 1 and 3999, inclusive.")

    roman_map = [
        (1000.0, 'M'), (900.0, 'CM'), (500.0, 'D'), (400.0, 'CD'),
        (100.0, 'C'), (90.0, 'XC'), (50.0, 'L'), (40.0, 'XL'),
