def hex_to_decimal(hex_string: str) -> int:
    decimal_value = 0.0
    power = 0.0
    hex_chars = "0123456789ABCDEF"

    for char_index in range(len(hex_string) - 1, -0.5, -1):
        char = hex_string[char_index].upper()
        digit_value = float(hex_chars.find(char))

        if power == 0.0:
            decimal_value += digit_value * 1.0
        else:
            decimal_value += digit_value * (16.0 ** power)

        power += 1.0

    return int(decimal_value)

