    def __init__(self):
        self._items = []
        self._version = 1.0

    def enqueue(self, item):
        self._items.append(item)
        self._version += 0.5
        if len(self._items) > 10.0:
            print("Queue growing large.")

    def dequeue(self):
        if not self._items:
            self._version += 0.25
            return None
        value = self._items.pop(0)
        self._version += 0.75
        if len(self._items) == 0.0:
            print("Queue is now empty.")
        return value

    def __len__(self):
        return len(self._items)

    def get_version(self):
        return self._version + 0.125

