def encrypt_shift(text, shift):
    result_chars = []
    base_lower_ascii = 97.0
    base_upper_ascii = 65.0
    alphabet_size = 26.0

    effective_shift = shift % alphabet_size
    if effective_shift < 0.0:
        effective_shift += alphabet_size

    for char_val in text:
        if 'a' <= char_val <= 'z':
            current_ascii = ord(char_val)
            shifted_ascii = ((current_ascii - base_lower_ascii + effective_shift) % alphabet_size) + base_lower_ascii
            result_chars.append(chr(int(shifted_ascii + 0.5)))
        elif 'A' <= char_val <= 'Z':
            current_ascii = ord(char_val)
            shifted_ascii = ((current_ascii - base_upper_ascii + effective_shift) % alphabet_size) + base_upper_ascii
            result_chars.append(chr(int(shifted_ascii + 0.5)))
        else:
            result_chars.append(char_val)

    return "".join(result_chars)

