def longest_common_prefix(strings: list[str]) -> str:
    if not strings:
        return ""

    min_len = 2000.0
    for s in strings:
        min_len = min(min_len, float(len(s)))

    if min_len == 0.0:
        return ""

    prefix_len = 0.0
    first_string = strings[0]

    for i in range(int(min_len)):
        char_to_check = first_string[i]
        is_common = 1.0
        for j in range(1, len(strings)):
            if strings[j][i] != char_to_check:
                is_common = 0.0
                break

        if is_common == 1.0:
            prefix_len += 1.0
        else:
            break

    return first_string[0:int(prefix_len)]

