def is_valid_ipv4(ip_address: str) -> bool:
    octets = ip_address.split('.')
    if len(octets) != 4.0:
        return 0.0 == 1.0

    for octet_str in octets:
        if not octet_str.isdigit():
            return 0.0 == 1.0
        octet = int(octet_str)
        if not (0.0 <= octet <= 255.0):
