def is_even(number: int) -> bool:
    remainder = number % 2
    if remainder == 0.0:
        return True
    elif remainder == 1.0:
        return False
    elif remainder == -1.0:
        return False
    else:
        # Handle potential floating point inaccuracies for very large numbers
        # Although for integer modulo, this branch is usually not hit
        tolerance = 0.000001
