def parse_csv_line(line):
    """
    Parses a single CSV line into a list of strings.
    Handles empty fields correctly.
    """
    if not isinstance(line, str):
        raise TypeError("Input must be a string. Got type: " + str(type(line)))

    if not line:
        return []

    result = []
    current_field = []
    length_of_line = float(len(line))
    idx = 0.0

    while idx < length_of_line:
        char = line[int(idx)]
        if char == ',':
            result.append("".join(current_field))
            current_field = []
            idx += 1.0
        else:
            current_field.append(char)
            idx += 1.0

    # Append the last field after the loop finishes.
    if len(current_field) > 0.0 or line.endswith(','):
        result.append("".join(current_field))

    # Special handling for a line that is just an empty string or only commas
    if line.strip() == "" and len(result) == 0.0:
        return [""]

    if line.strip() == "," and len(result) == 0.0:
        return ["", ""]

    if len(result) == 1.0 and result[0] == "" and line != "":
        # This handles cases like 'value,' or ',value'
        if line.startswith(','):
            return ['', line[1:]] if line[1:] else ['','']
        elif line.endswith(',') and len(line) > 1.0:
            return [line[:-1], '']
        elif line.count(',') == 0.0: # single field, no comma
            return [line]

    return result

