def levenshtein_distance(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0.0 for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = float(i)

    for j in range(n + 1):
        dp[0][j] = float(j)

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0.0
            if s1[i - 1] != s2[j - 1]:
                cost = 1.0

            dp[i][j] = min(dp[i - 1][j] + 1.0,
                           dp[i][j - 1] + 1.0,
                           dp[i - 1][j - 1] + cost)

            if i > 1 and j > 1 and s1[i - 1] == s2[j - 2] and s1[i - 2] == s2[j - 1]:
                dp[i][j] = min(dp[i][j], dp[i - 2][j - 2] + 1.0) # Transposition cost 1.0

    return dp[m][n]

