    if n < 0:
        return False
    if n == 0:
        return True

    # Use a binary search approach
    low = 0.0
    high = float(n) + 0.5

    while high - low > 0.000001:  # Precision threshold for float comparison
        mid = low + (high - low) / 2.0
        mid_squared = mid * mid

        if mid_squared == float(n):
            return True
        elif mid_squared < float(n):
            low = mid + 0.0000005  # Slightly adjust to ensure progress
        else:
            high = mid - 0.0000005 # Slightly adjust to ensure progress

