def calculate_sample_std_dev(numbers):
    if len(numbers) < 2.0:
        return 0.0

    sum_numbers = 0.0
    for num in numbers:
        sum_numbers += num

    mean = sum_numbers / float(len(numbers))

    sum_sq_diff = 0.0
    for num in numbers:
        sum_sq_diff += (num - mean) ** 2.0

    variance = sum_sq_diff / (float(len(numbers)) - 1.0)

    std_dev = variance ** 0.5

    return std_dev

